INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29901, 'Revelation 19:15', 'Revelation', 19, 15, '&nbsp;او د هغۀ د خولې نه يوه تيره تُوره راوځى چې قومونه پرې ووهى، ځکه چې هغه به په هغوئ زورَور حکومت کوى او د ګناهونو د انګورو لنګرۍ به د قادر مطلق خُدائ پاک د قهر او غضب د پښو لاندې نچوړ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29902, 'Revelation 19:16', 'Revelation', 19, 16, '&nbsp;او د هغۀ په چُوغه او په پتُون دا نوم ليکلے دے چې، ”د بادشاهانو بادشاه او د مالِکانو مالِک.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29903, 'Revelation 19:17', 'Revelation', 19, 17, '&nbsp;بيا ما يوه فرښته په نمر کښې ولاړه وليده او هغې بره په آسمان کښې الوتونکو مارغانو ته چغې کړې چې، ”راشئ او د خُدائ پاک په لويه مېلمستيا کښې راجمع شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29904, 'Revelation 19:18', 'Revelation', 19, 18, '&nbsp;چې د بادشاهانو او د کمانډرانو او د تکړه سپاهيانو غوښې، د آسونو او د هغوئ د سورو غوښې او د ټولو خلقو، غلامانو او آزادو د لويو او د وړو غوښې وخورئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29905, 'Revelation 19:19', 'Revelation', 19, 19, '&nbsp;بيا ما وليدل چې بلا او د دُنيا بادشاهان او د هغوئ لښکرې د سوارۀ او د هغۀ د لښکر سره په جنګ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29906, 'Revelation 19:20', 'Revelation', 19, 20, '&nbsp;او هغه بلا ګرفتار کړے شوه او دغسې هغه دروغژن نبى هم چې يې د هغې دپاره معجزې ښکاره کولې او هغه څوک يې دوکه کول په چا چې د بلا نښه وه او د هغۀ بُت ته يې سجده کړې وه. دغه دواړه ژوندى هغه درياب ته وغورزولے شول چې د ګوګړو شُغلې ترېنه ختلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29907, 'Revelation 19:21', 'Revelation', 19, 21, '&nbsp;او باقى په هغه تُوره ووژلے شول چې په سپين آس د سوارۀ له خولې نه راوتله، او ټولو مارغانو د هغوئ په غوښه ځانونه ماړۀ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29908, 'Revelation 20:1', 'Revelation', 20, 1, '&nbsp;بيا ما يوه فرښته له آسمان نه په راکوزېدو وليدله چې ورسره د عالِم ارواح کُنجى او په لاس کښې يې لوئ زنځير وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29909, 'Revelation 20:2', 'Revelation', 20, 2, '&nbsp;او هغه اژدها چې زوړ ښامار دے، هغه يې ونيوو، اِبليس يعنې شېطان، او تر زرو کالو پورې يې وتړلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29910, 'Revelation 20:3', 'Revelation', 20, 3, '&nbsp;فرښتې هغه عالِم ارواح ته وغورزولو، بند يې کړو او مهر يې پرې ولګولو، د دې دپاره چې هغه بيا تر هغې قومونه دوکه نۀ کړى ترڅو چې زر کاله پوره شوى نۀ وى. د هغې نه پس به هغه بيا د لږ وخت دپاره آزاد کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29911, 'Revelation 20:4', 'Revelation', 20, 4, '&nbsp;بيا ما يو څو تختونه وليدل او هغه خلق پرې ناست وُو چا ته چې د عدالت اختيار ورکړے شوے وو. ما د هغه خلقو روحونه وليدل چې سرونه يې د خُدائ پاک د کلام او د عيسىٰ د شهادت په وجه پرې کړے شوى وُو، او هغه خلق چا چې بلا يا د هغۀ بُت ته سجده نۀ وه کړې او نۀ يې په لاس يا تندى د هغۀ نښه لګولې وه. هغوئ بيا راژوندى شول او د مسيح سره يې تر زرو کالو بادشاهى وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29912, 'Revelation 20:5', 'Revelation', 20, 5, '&nbsp;باقى مړى تر هغې ژوندى نۀ کړے شول ترڅو چې زر کاله پوره شوى نۀ وُو. دا اولنے قيامت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29913, 'Revelation 20:6', 'Revelation', 20, 6, '&nbsp;بختور او قُدوس هغه دے چې په دې اولنى قيامت کښې شريک دے. ځکه چې په داسې خلقو د دوېم مرګ اختيار نۀ وى بلکې هغوئ به د خُدائ پاک او د مسيح اِمامان وى او د هغۀ سره به تر زرو کالو پورې بادشاهى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29914, 'Revelation 20:7', 'Revelation', 20, 7, '&nbsp;هر کله چې زر کاله پوره شى نو شېطان به د قېد خانې نه را آزاد شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29915, 'Revelation 20:8', 'Revelation', 20, 8, '&nbsp;او هغه به راشى او په څلور ګوټه دُنيا کښې به قومونه دوکه کړى، يعنې جوج او ماجوج، او جنګ ته به يې راجمع کړى چې د سمندر د شګو په شان بې‌شمېره دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29916, 'Revelation 20:9', 'Revelation', 20, 9, '&nbsp;نو هغوئ په ټوله دُنيا راخوارۀ شول او د خُدائ پاک د مقدسينو دېره او د هغۀ محبوب ښار يې راګېر کړو، خو د آسمان نه اور پرې نازل شو او هغوئ يې تباه کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29917, 'Revelation 20:10', 'Revelation', 20, 10, '&nbsp;او بيا هغوئ له دوکه ورکوونکے اِبليس د اور او ګوګړو درياب ته وغورزولے شو چرته چې بلا او دروغژن نبى هم ورغورزولے شوے دے او هلته به په شپه او ورځ تل تر تله عذابولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29918, 'Revelation 20:11', 'Revelation', 20, 11, '&nbsp;بيا ما يو لوئ سپين تخت وليدو چې يو کس چې پرې ناست وو، د هغۀ د حضور نه زمکه او آسمان وتښتېدل او غېب شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29919, 'Revelation 20:12', 'Revelation', 20, 12, '&nbsp;بيا ما لوئ او واړۀ مړى د تخت د وړاندې ولاړ وليدل او کتابونه پرانستلے شول. بيا بل کِتاب پرانستلے شو، يعنې د ژوندون کِتاب. او د مړو عدالت د هغوئ د اعمالو په مطابق وشو څنګه چې په هغه کتابونو کښې درج وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29920, 'Revelation 20:13', 'Revelation', 20, 13, '&nbsp;سمندر خپل مړى چې په کښې وُو، ورکړل بيا مرګ او عالمِ ارواح خپل مړى ورکړل چې په کښې وُو او د ټولو عدالت د هر چا د خپل عمل په مطابق وشو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29921, 'Revelation 20:14', 'Revelation', 20, 14, '&nbsp;بيا مرګ او عالمِ ارواح د اور درياب ته وغورزولے شول، د اور درياب دوېم مرګ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29922, 'Revelation 20:15', 'Revelation', 20, 15, '&nbsp;خو د چا نومونه چې د ژوندون په کِتاب کښې درج نۀ وُو هغوئ د اور په درياب کښې وغورزولے شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29923, 'Revelation 21:1', 'Revelation', 21, 1, '&nbsp;بيا ما يو نوے آسمان او يوه نوې دُنيا وليدله ځکه چې اول آسمان او اوله دُنيا غېب شوى وُو او سمندر هم نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29924, 'Revelation 21:2', 'Revelation', 21, 2, '&nbsp;ما پاک ښار، يعنې نوے يروشلم وليدلو چې د خُدائ پاک د طرفه د آسمان نه راکوزېدو، او دا داسې تيار کړے شوے وو لکه چې ناوې د خپل خاوند دپاره سنګار شوې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29925, 'Revelation 21:3', 'Revelation', 21, 3, '&nbsp;ما د تخت نه يو اوچت آواز واورېدو چې دا يې فرمائيل چې، ”ګورئ، اوس به د خُدائ پاک حضور د بنى آدمو په مينځ کښې وى او هغوئ به د هغۀ اُمت وى او خُدائ پاک به په خپله د هغوئ سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29926, 'Revelation 21:4', 'Revelation', 21, 4, '&nbsp;هغه به د هغوئ د سترګو ټولې اوښکې وچې کړى، هلته به نور نۀ مرګ، نۀ وير، نۀ ژړا او نۀ درد وى ځکه چې وړومبى څيزونه تېر شوى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29927, 'Revelation 21:5', 'Revelation', 21, 5, '&nbsp;او هغه څوک چې په تخت ناست وو هغۀ وفرمائيل چې، ”وګورئ، زۀ ټول څيزونه نوى کوم.“ بيا هغۀ ما ته وفرمائيل چې، ”زما دا کلام وليکه ځکه چې زما خبرې د اِعتبار لائقې او رښتيا دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29928, 'Revelation 21:6', 'Revelation', 21, 6, '&nbsp;بيا يې ما ته وفرمائيل چې، ”وشوه. الفه او اوميګه، اول او آخر زۀ يم. هر څوک چې تږے وى زۀ به هغوئ ته د ژوندون د اوبو د چينو نه وړيا اوبۀ ورکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29929, 'Revelation 21:7', 'Revelation', 21, 7, '&nbsp;څوک چې کامياب شى هغه به د دې وارث شى، او زۀ به د هغوئ خُدائ پاک يم او هغوئ به زما بچى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29930, 'Revelation 21:8', 'Revelation', 21, 8, '&nbsp;خو د ويرېدونکو، بې‌ايمانانو، پليتانو، قاتلانو، حرامکارانو، جادوګرانو، بُت پرستانو او هر قسم دروغژن خلق به په هغه درياب کښې وى چې په کښې د ګوګړو اور بليږى، او دا دوېم مرګ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29931, 'Revelation 21:9', 'Revelation', 21, 9, '&nbsp;بيا په هغه اوو فرښتو کښې چې د اووۀ آخرى افتونو ډک جامونه ورسره وُو، يوه ما ته راغله او وې وئيل چې، ”راځه، زۀ به تا ته ناوې وښايم چې د ګډُورى ښځه ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29932, 'Revelation 21:10', 'Revelation', 21, 10, '&nbsp;نو روحُ القُدس په ما غلبه وکړه او زۀ يې يو لوئ اوچت غر ته بوتلم او د يروشلم پاک ښار يې راته وښائيلو چې د خُدائ پاک د طرفه راکوزېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29933, 'Revelation 21:11', 'Revelation', 21, 11, '&nbsp;هغه د خُدائ پاک په جلال روښانه وو، د هغې رڼا د قيمتى جواهراتو په شان لکه د جاسپر او د بلور کاڼى په شان صفا وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29934, 'Revelation 21:12', 'Revelation', 21, 12, '&nbsp;د هغې لوئ اوچت دېوال وو چې په کښې دولس دروازې وې او په هره دروازه کښې فرښته ولاړه وه، او په دروازو د بنى اِسرائيلو د دولسو قبيلو نومونه ليکلے شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29935, 'Revelation 21:13', 'Revelation', 21, 13, '&nbsp;نمرخاتۀ ته درې دروازې وې، شمال ته درې، جنوب ته درې، او نمر پرېواتۀ ته درې دروازې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29936, 'Revelation 21:14', 'Revelation', 21, 14, '&nbsp;د ښار د دېوال دولس بنيادونه وُو او په هغې د ګډُورى د دولسو رسولانو نومونه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29937, 'Revelation 21:15', 'Revelation', 21, 15, '&nbsp;کومې فرښتې چې ما سره خبرې وکړلې، د هغې سره د سرو زرو يو ګز وو چې پرې د ښار دېوالونه او دروازې ناپ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29938, 'Revelation 21:16', 'Revelation', 21, 16, '&nbsp;او ښار په څلور ګوټه شکل جوړ وو او څومره چې اوږد وو هغه هومره پلن وو، او هغې د ښار ناپ په ګز وکړو او د دې اوږدوالے، پلنوالے او اوچتوالے برابر وُو چې دوه نيم زره کيلوميټره وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29939, 'Revelation 21:17', 'Revelation', 21, 17, '&nbsp;فرښتې د ديوال ناپ په دُنياوى پېمانه وکړو چې شپېتۀ ميټره اوچت وو، او فرښتې هم دا پېمانه استعمالوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29940, 'Revelation 21:18', 'Revelation', 21, 18, '&nbsp;دېوال د جاسپر کاڼو نه جوړ وو او ښار په خپله د سوچه سرو زرو نه جوړ شوے وو او د صفا شيشې په شان پړقېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29941, 'Revelation 21:19', 'Revelation', 21, 19, '&nbsp;د ښار د دېوالونو بنيادونه په رنګا رنګ قيمتى کاڼو ښائسته کړے شوى وُو اول بنياد د جاسپر کاڼو وو، دوېم د نيلم، درېم د شب چراغ، څلورم د زمرد،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29942, 'Revelation 21:20', 'Revelation', 21, 20, '&nbsp;پينځم د اونيکس، شپږم د يمنى عقيقو، اوؤم د ګراسولر، اتم د ايکوامرين، نهم د طوپاز، لسم د کلسائټو، يوولسم د کائنائټو، او دولسم د کټېلى وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29943, 'Revelation 21:21', 'Revelation', 21, 21, '&nbsp;او هغه دولس دروازې د دولسو ملغلرو وې، هره دروازه د يوې ملغلرې نه جوړه وه. د ښار لوئې کوڅې د صفا شيشې په شان د سوچه سرو زرو وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29944, 'Revelation 21:22', 'Revelation', 21, 22, '&nbsp;ما په ښار کښې د خُدائ کور ونۀ ليدو ځکه چې مالِک قادر مطلق خُدائ پاک او ګډُورے په خپله د دې ښار د خُدائ پاک کور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29945, 'Revelation 21:23', 'Revelation', 21, 23, '&nbsp;او ښار ته د نمر يا د سپوږمۍ د رڼا حاجت نشته ځکه چې د خُدائ پاک جلال دا روښانه کوى او ګډورے د دې ډيوه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29946, 'Revelation 21:24', 'Revelation', 21, 24, '&nbsp;د دې په رڼا به قومونه ګرځى او دۀ ته به د دُنيا بادشاهان خپلې لويئ راوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29947, 'Revelation 21:25', 'Revelation', 21, 25, '&nbsp;د ښار دروازې به ټوله ورځ کښې نۀ بنديږى او هلته به شپه چرې نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29948, 'Revelation 21:26', 'Revelation', 21, 26, '&nbsp;د قومونو شان او شوکت به دۀ ته راوړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29949, 'Revelation 21:27', 'Revelation', 21, 27, '&nbsp;خو هيڅ ناپاکه څيز به دې ته ورننوتے نۀ شى او نۀ پليت او نۀ دروغژن، خو صرف هغوئ د چا نومونه چې د ګډُورى د ژوندون په کِتاب کښې ليکلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29950, 'Revelation 22:1', 'Revelation', 22, 1, '&nbsp;بيا فرښتې ما ته د ژوند د اوبو درياب وښودلو چې د بلور په شان پړقېدو چې د خُدائ پاک او د ګډُورى د تخت نه', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29951, 'Revelation 22:2', 'Revelation', 22, 2, '&nbsp;د ښار د لوئ سړک په مينځ کښې رابهېدلو. د درياب په دواړو غاړو د ژوندون ونه وه چې دولس قسمه مېوه يې نيوله او هره مياشت به يې مېوه نيوله. او د ونې پاڼې د قومونو د شفا ورکولو دپاره دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29952, 'Revelation 22:3', 'Revelation', 22, 3, '&nbsp;او په هغه ښار کښې به داسې هيڅ څيز موندلے نۀ شى چې ناروا وى. او د خُدائ پاک او د ګډورى تخت به په هغه ښار کښې وى او د هغۀ خادِمان به د هغۀ عبادت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29953, 'Revelation 22:4', 'Revelation', 22, 4, '&nbsp;هغوئ به د هغۀ مخ وينى او د هغۀ نوم به د هغوئ په تندو ليکلے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29954, 'Revelation 22:5', 'Revelation', 22, 5, '&nbsp;هلته به شپه نۀ وى او نۀ به هغوئ ته د ډيوې يا د نمر د رڼا ضرورت وى ځکه چې مالِک خُدائ پاک به د هغوئ رڼا وى، او هغوئ به هلته تل تر تله بادشاهى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29955, 'Revelation 22:6', 'Revelation', 22, 6, '&nbsp;بيا فرښتې ما ته ووئيل چې، ”دا خبرې د اِعتبار لائقې او رښتيا دى. مالِک خُدائ پاک چې خپلو نبيانو ته د نبوت الهام ورکوى، هغۀ خپله فرښته راولېږله چې خپلو خادِمانو ته هغه څۀ وښائى چې زر کېدونکى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29956, 'Revelation 22:7', 'Revelation', 22, 7, '&nbsp;مالِک عيسىٰ فرمائى چې، ”ما ته غوږ ونيسئ زۀ زر درځم. بختور دى هغوئ څوک چې د دې کِتاب پېشګوئې منى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29957, 'Revelation 22:8', 'Revelation', 22, 8, '&nbsp;او زۀ يوحنا هغه څوک يم چې دا رويا مې واورېدله او وليدله. نو زۀ د هغې فرښتې په پښو کښې په سجده پرېوتلم چا چې ما ته دا هر څۀ ښکاره کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29958, 'Revelation 22:9', 'Revelation', 22, 9, '&nbsp;خو هغې ما ته ووئيل، ”داسې مۀ کوه، زۀ خو ستا او ستا د وروڼو نبيانو او د دې کِتاب د کلام منونکو، په شان يو خادِم يم. صرف خُدائ پاک ته سجده کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29959, 'Revelation 22:10', 'Revelation', 22, 10, '&nbsp;بيا هغې ما ته ووئيل چې، ”د دې کِتاب پېشګوئې مۀ پټوه ځکه چې د هغې د پوره کېدو وخت رانزدې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29960, 'Revelation 22:11', 'Revelation', 22, 11, '&nbsp;څوک چې بدکاران دى، پرېږده چې بدکارونه کوى، څوک چې پليت دى، پرېږدئ چې په خپله پليتۍ کښې آخته وى. څوک چې صادقان دى هغه دې په خپل صداقت کښې پاتې شى او څوک چې پاک وى هغوئ دې پاک پاتې شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29961, 'Revelation 22:12', 'Revelation', 22, 12, '&nbsp;”ما ته غوږ ونيسئ. زۀ عيسىٰ زر درځم او ستاسو اجر د خپل ځان سره دروړم چې هر يو ته به زۀ د هغوئ د عمل په مطابق ورکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29962, 'Revelation 22:13', 'Revelation', 22, 13, '&nbsp;الفه او اوميګه زۀ يم، اول او آخر زۀ يم، ازل او خاتمه زۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29963, 'Revelation 22:14', 'Revelation', 22, 14, '&nbsp;بختور دى هغه خلق چې خپلې چُوغې يې صفا وينځلى دى، نو هم هغوئ به د ژوندون د ونې حق ومومى او ښار ته به په دروازو ورننوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29964, 'Revelation 22:15', 'Revelation', 22, 15, '&nbsp;خو بهر هغه سپى دى کوم چې جادوګران، حرامکاران، قاتلان او بُت پرستان او د هغوئ ټولو د ژوند هر يو پل په دروغو روان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29965, 'Revelation 22:16', 'Revelation', 22, 16, '&nbsp;ما عيسىٰ، خپله فرښته تاسو ته درولېږله چې جماعتونو ته دا ګواهى ورکړى چې زۀ د داؤد د څانګې او نسل نه يم او د سبا ځلېدونکے ستورے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29966, 'Revelation 22:17', 'Revelation', 22, 17, '&nbsp;روحُ القُدس او ناوې وائى چې، ”راشه.“ او هر اورېدونکے دې هم وائى چې، ”راشه.“ او څوک چې تږے وى، هغه دې راشى، او څوک چې يې غواړى، د ژوندون د اوبو نه دې وړيا واخلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29967, 'Revelation 22:18', 'Revelation', 22, 18, '&nbsp;زۀ هر چا ته دا خبردارے ورکوم څوک د دې کِتاب د پېشګويو کلام اورى، کۀ څوک د ځانه څۀ په کښې زيات کړى نو خُدائ پاک به هغۀ ته په دې کِتاب کښې بيان شوى افتونه ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29968, 'Revelation 22:19', 'Revelation', 22, 19, '&nbsp;او کۀ څوک د پېشګويو د دې کِتاب نه څۀ خبرې اخوا کړى نو خُدائ پاک به د هغۀ د ژوندون د ونې نه او د مقدس ښار نه د هغۀ حِصه ختمه کړى کومه چې په دې کِتاب کښې بيان شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29969, 'Revelation 22:20', 'Revelation', 22, 20, '&nbsp;څوک چې د دې خبرو ګواهى ورکوى هغه وائى چې، ”آو، زۀ زر درځم.“ آمين، مالِک عيسىٰ، راشه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29970, 'Revelation 22:21', 'Revelation', 22, 21, '&nbsp;د مالِک عيسىٰ فضل دې په تاسو ټولو وى، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29971, 'Matthew 23:13', 'Matthew', 23, 13, 'عیسی زیاته کړه: «ای منافقانو د شریعت عالمانو او فریسیانو! ستاسو په حال دې افسوس وي، ځکه چې تاسو د اسماني پاچاهۍ دروازې د خلکو دپاره بندوئ، نه تاسو ورننوځئ او نه نور خلک پرېږدئ چې ورننوځي. [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29972, 'Matthew 23:14', 'Matthew', 23, 14, 'ای منافقانو د شریعت عالمانو او فریسیانو! ستاسو په حال دې افسوس وي، ځکه چې تاسو د کونډو مالونه خورئ، خو د ځان ښودنې دپاره اوږدې اوږدې دعاګانې کوئ، خو خدای به تاسو ته د نورو څخه سخته سزا درکړي.]', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29973, 'Acts 8:36', 'Acts', 8, 36, 'څنګه چې هغوی په لاره روان وو، نو یو داسې ځای ته ورسېدل چې هلته اوبه وې او هغه مامور وویل: «ګوره چې دلته اوبه شته، نو څه شی زما د تعمید د غسل اخیستلو مخه نیولی شي؟» [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29974, 'Acts 8:37', 'Acts', 8, 37, 'فیلیپوس وویل: «که چېرې ته د زړه نه ایمان راوړې، نو بیا کولای شې.» هغه ځواب ورکړ: «زه ایمان لرم چې عیسی مسیح د خدای زوی دی.»]', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29975, 'Mark 11:25', 'Mark', 11, 25, 'او هرکله چې تاسو د دعا دپاره ودرېږئ، نو که ستاسو په زړونو کې د چا په خلاف کوم څه شی وي هغه وبخښئ، ترڅو ستاسو اسماني پلار هم ستاسو ګناهونه وبخښي.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29976, 'Mark 11:26', 'Mark', 11, 26, '[خو که چېرې تاسو نور خلک ونه بخښئ، نو ستاسو اسماني پلار به هم ستاسو ګناهونه ونه بخښي.]» د عیسی د اختیار په هکله پوښتنه (متي ۲۱‏:‌۲۳‌‏-‌۲۷ او لوقا ۲۰‏:‌۱‌‏-‌۸)', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29977, 'Mark 15:27', 'Mark', 15, 27, 'د هغه سره یې دوه داړه ماران هم په صلیب باندې ځوړند کړل، یو د هغه ښي لاس ته او بل چپ لاس ته. [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29978, 'Mark 15:28', 'Mark', 15, 28, 'په دې ډول د پیغمبرانو هغه لیکنې پوره شوې چې وایي: «هغه په بدکارانو کې وشمېرل شو.»]', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29979, 'Acts 15:33', 'Acts', 15, 33, 'هلته د څه وخت تېرولو نه وروسته هغوی د ایماندارانو له خوا په خیریت سره رخصت شول او بېرته هغو خلکو ته ورغلل چې دوی یې لېږلي وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29980, 'Acts 15:34', 'Acts', 15, 34, '‏-۳۵ خو پولوس او برناباس په انطاکیه کې پاتې شول او هلته یې د ډېرو نورو سره یوځای تعلیم ورکاوه او د څښتن عیسی پیغام یې اوراوه. د پولوس او برناباس بېلېدل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29981, 'Acts 28:28', 'Acts', 28, 28, 'نو بیا پوه شئ چې دغه د خلاصون پیغام د خدای له خوا غیریهودیانو ته لېږل شوی دی او هغوی به یې مني.» [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29982, 'Acts 28:29', 'Acts', 28, 29, 'کله چې پولوس خپلې خبرې پای ته ورسولې، نو یهودیان لاړل او په خپل منځ کې یې سره بحث وکړ.]', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29983, 'Mark 9:43', 'Mark', 9, 43, 'که چېرې ستا لاس ستا د ګناه سبب وګرځي، نو هغه پرې کړه، ځکه چې ستا دپاره به دا ښه وي چې د یو لاس سره تلپاتې ژوندون ته لاره پیدا کړې، نه دا چې د دوو لاسونو سره دوزخ ته لاړ شې یعنې هغه اور ته چې هېڅکله نه مړ کیږي، [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29984, 'Mark 9:44', 'Mark', 9, 44, 'هغه ځای ته چې چینجي یې نه مړه کیږي او اور یې نه مړ کیږي.]', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29985, 'Mark 9:45', 'Mark', 9, 45, 'که چېرې ستا پښه ستا د ګناه سبب وګرځي، نو هغه پرې کړه. ځکه چې دا ښه ده چې د یوې پښې سره تلپاتې ژوندون ته لاره پیدا کړې، نه دا چې دواړه پښې دې روغې وي او دوزخ ته واچول شې، [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29986, 'Mark 9:46', 'Mark', 9, 46, 'هغه ځای ته چې چینجي یې نه مړه کیږي او اور یې نه مړ کیږي.]', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29987, 'Matthew 17:20', 'Matthew', 17, 20, 'هغه ورته وویل: «ځکه چې ستاسو ایمان کمزوری دی. په یقین سره زه تاسو ته دا وایم چې که چېرې تاسو د شړشمو د دانې په اندازه ایمان هم ولرئ، نو کولای شئ دې غره ته ووایئ چې د دې ځای څخه هغه ځای ته لاړ شه، نو هغه به لاړ شي او هېڅ کار به ستاسو دپاره ناشونی نه وي. [', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29988, 'Matthew 17:21', 'Matthew', 17, 21, 'دا ډول پېریان یوازې په دعا کولو او د روژې په نیولو سره کېدای شي وویستل شي.]» عیسی یوځل بیا د خپل مرګ په هکله خبرې کوي (مرقوس ۹‏:‌۳۰‌‏-‌۳۲ او لوقا ۹‏:‌۴۳‌‏-‌۴۵)', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29989, 'Deuteronomy 16:5', 'Deuteronomy', 16, 5, 'تاسو باید د فسحې د اختر قرباني په هېڅ ښار کې چې خپل څښتن خدای یې درکوي وړاندې نه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29990, 'Deuteronomy 16:6', 'Deuteronomy', 16, 6, 'دا قرباني باید یوازې په هغه ځای کې وړاندې شي چې څښتن یې د خپل عبادت دپاره غوره کوي. د قربانۍ حیوان د لمرپرېواته په وخت کې حلال کړئ، ځکه چې تاسو د مصر څخه د لمرپرېواته په وخت کې راووتلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29991, 'Isaiah 59:5', 'Isaiah', 59, 5, 'د هغوی نقشې د مار د هګیو په شان دي چې کله ماتې شي، نو د خلکو د تباهۍ دپاره کارول کیږي. خو دا نقشې هم د غڼو د جالونو په شان دي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29992, 'Isaiah 59:6', 'Isaiah', 59, 6, 'هغوی نه شي کولای چې د غڼو د تارونو څخه کالي جوړ کړي، ترڅو خپل ځانونه ورباندې پټ کړي. هر ډول بد عملونه د هغوی له خوا رامنځته کیږي او لاسونه یې د خلکو د تباه کولو دپاره تیار دي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29993, 'Joshua 5:4', 'Joshua', 5, 4, 'نو په دې خاطر هغه داسې وکړل. هغه ټول نارینه یعنې ټول جنګي کسان چې د مصر څخه راوتلي وو، د سفر په دوران کې په دښته کې مړه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29994, 'Joshua 5:5', 'Joshua', 5, 5, 'هغه خلک چې د مصر څخه راوتلي وو هغوی ټول سنت شوي وو، خو هغه ټول خلک چې د سفر په دوران کې په دښته کې زېږېدلي وو، هغوی سنت شوي نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29995, 'Joshua 5:6', 'Joshua', 5, 6, 'اسراییلیانو څلوېښت کاله په دښته کې سفر وکړ، تر هغې چې ټول خلک یعنې د قوم ټول جنګي کسان چې د مصر څخه راووتل مړه شول، ځکه چې د څښتن د امر څخه یې سرغړونه کړې وه. لکه څنګه چې څښتن قسم خوړلی ؤ، هغوی ته اجازه ورنه کړای شوه چې هغه غني او حاصلخېزه ځمکه وویني چې د هغو د نیکونو سره یې وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29996, 'Leviticus 11:4', 'Leviticus', 11, 4, 'خو داسې حیوانات شته چې یوازې شخوند وهونکي دي یا یوازې خلاص سوم لري، خو تاسو باید د هغو غوښه ونه خورئ. لکه اوښ، که څه هم هغه شخوند وهونکی دی، خو خلاص سوم نه لري. دا ستاسو دپاره ناپاک دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29997, 'Leviticus 11:5', 'Leviticus', 11, 5, 'غرنۍ سویه، که څه هم هغه شخوند وهونکې ده خو خلاص سوم نه لري، دا ستاسو دپاره ناپاکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29998, 'Leviticus 11:6', 'Leviticus', 11, 6, 'سویه که څه هم شخوند وهونکې ده، خو خلاص سوم نه لري. دا ستاسو دپاره ناپاکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29999, 'Leviticus 11:29', 'Leviticus', 11, 29, 'د هغو حیواناتو څخه چې په ځمکه باندې ګرځي، دغه حیوانات ستاسو دپاره ناپاک دي: ړنده مږه، موږک، هر ډول سمساره،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30000, 'Leviticus 11:30', 'Leviticus', 11, 30, 'ډول ډول د کور او د شګې چرمښکۍ او کربوړی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');